pub async fn probe_response(kind: &str) -> Vec<u8> {
    let data = Bytes::from_static(b"abc");
    let body = match kind {
        "fixed" => Body::from(data),
        "empty" => Body::stream(futures_util::stream::empty()),
        "chunked" => Body::stream(futures_util::stream::iter([Ok(data)])),
        "trailers" | "empty-trailers" => {
            let mut trailers = http::HeaderMap::new();
            if kind == "trailers" { trailers.insert("x-check", http::HeaderValue::from_static("yes")); }
            Body::frames(futures_util::stream::iter([Ok(Frame::data(data)), Ok(Frame::trailers(trailers))]))
        }
        _ => unreachable!(),
    };
    let mut response = Response::new(body);
    response.headers_mut().insert("date", http::HeaderValue::from_static("Sun, 18 Oct 2026 12:00:00 GMT"));
    let mut wire = Futures(futures_util::io::Cursor::new(Vec::with_capacity(8192)));
    let mut output = Vec::with_capacity(8192);
    write_response(&mut wire, &mut output, response, false, http::Version::HTTP_11, false, &Limits::default(), &Activity::new()).await.unwrap();
    wire.0.into_inner()
}

